import numpy as np

class ModulatedSineWaves:
    def __init__(self, dim=5):
        self.dim = dim
        # Frequency increases with dimension index to create varying oscillation tightness
        self.frequencies = np.arange(1, dim + 1) * 2.0

    def f(self, x):
        # Each dimension contributes a sine wave with increasing frequency
        # The amplitude decreases with dimension to balance contribution
        terms = x ** 2 * np.sin(self.frequencies * np.pi * x) ** 2
        return np.sum(terms)

