class PolynomialPeriodicWells:
    def __init__(self, dim):
        self.dim = dim
        self.amplitude = 0.5  # Controls depth of periodic wells
        self.global_weight = 0.01  # Weight for global x^4 term
        self.period = 2.0 * np.pi  # Period of the sinusoidal wells

    def f(self, x):
        if len(x) != self.dim:
            raise ValueError(f"Expected input of dimension {self.dim}, got {len(x)}")
        # Periodic wells: sin^2 creates local minima at k*pi
        # Global term: x^4 ensures origin is unique global minimum
        periodic_term = self.amplitude * np.sin(x / self.period)**2
        global_term = self.global_weight * x**4
        return np.sum(periodic_term + global_term)
